{
  "candidates": [
    {
      "explanation": "Refinement of best prior (llm_r0_2). The emergency has caused sustained high demand (recent=20, baseline=18.55) and all nodes have zero inventory with significant backlog, especially node0 (backlog=97). The pipeline is substantial (80,76,76) and arrivals are high (20,16,20), so upstream orders should be relaxed to avoid over-ordering and excess inventory. Node0 needs a modest boost to clear its large backlog, but only when pipeline is not too high to prevent further backlog buildup. Node1 and node2 should reduce orders when pipeline is high to prevent upstream backlog. The rules are ordered first-match, so the first applicable rule per node is used.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 20 and pipeline < 40",
          "delta": "min(2, backlog / 20)"
        },
        {
          "when": "agent == 0 and pipeline >= 40",
          "delta": "-1"
        },
        {
          "when": "agent == 1 and pipeline > 50",
          "delta": "-1"
        },
        {
          "when": "agent == 2 and pipeline > 40",
          "delta": "-1"
        }
      ]
